#!/usr/bin/env python3
"""Collect the working-tree changes an agent made, ready to upload as an artifact.

Usage (from the repository root, after the agent step):

    python3 .github/free-pi/changed-files.py [outdir]

Writes:

    <outdir>/files/...          every added/modified/renamed file, same folder layout
    <outdir>/deleted-files.txt  one path per line for every file the agent deleted
    <outdir>/changed-files.txt  `<status> <path>` per change, renames show the old path

Generated by this workflow (output logs, diffs, the outdir itself) is ignored.
Nothing here fails the job: problems are reported and skipped.
"""

import os
import shutil
import subprocess
import sys

OUT = sys.argv[1] if len(sys.argv) > 1 else "free-pi-changes"
FILES = os.path.join(OUT, "files")
DELETED = os.path.join(OUT, "deleted-files.txt")
CHANGED = os.path.join(OUT, "changed-files.txt")

# Paths this workflow itself produces, never part of the agent's change set.
SKIP_EXACT = {OUT, DELETED, CHANGED}
SKIP_PREFIX = (
    OUT.rstrip("/") + "/",
    "free-pi-output.",
    "diff.txt",
    "diff-capped.txt",
    "review.md",
)
MAX_BYTES = 25 * 1024 * 1024  # keep the artifact well under the upload limit


def git_status():
    """Return [(xy, path, original_path_or_None)] from git status --porcelain -z."""
    proc = subprocess.run(
        ["git", "status", "--porcelain=v1", "-z", "--untracked-files=all", "--", "."],
        capture_output=True,
        check=False,
    )
    if proc.returncode != 0:
        print(proc.stderr.decode("utf-8", "replace").strip(), file=sys.stderr)
        return []
    fields = proc.stdout.decode("utf-8", "replace").split("\0")

    entries = []
    i = 0
    while i < len(fields):
        entry = fields[i]
        i += 1
        if not entry.strip():
            continue
        xy, path = entry[:2], entry[3:]
        original = None
        if xy[0] in "RC" or xy[1] in "RC":
            if i < len(fields):
                original = fields[i]
                i += 1
        entries.append((xy, path, original))
    return entries


def skipped(path):
    return path in SKIP_EXACT or path.startswith(SKIP_PREFIX)


def main():
    os.makedirs(FILES, exist_ok=True)

    deleted, copied, failed = [], [], []
    changed_lines = []

    for xy, path, original in git_status():
        if skipped(path):
            continue
        if xy == "!!":
            continue

        note = f" (from {original})" if original else ""
        changed_lines.append(f"{xy} {path}{note}")

        if "D" in xy:
            deleted.append(path)
            continue

        src = os.path.join(path)
        if not os.path.isfile(src) or os.path.islink(src):
            # Submodule, worktree dir, or something already gone.
            failed.append(f"{path} (not a regular file)")
            continue
        size = os.path.getsize(src)
        if size > MAX_BYTES:
            failed.append(f"{path} ({size / 1024 / 1024:.1f} MB, too large)")
            continue

        dest = os.path.join(FILES, path)
        try:
            os.makedirs(os.path.dirname(dest) or ".", exist_ok=True)
            shutil.copy2(src, dest)
        except OSError as err:
            failed.append(f"{path} ({err.strerror or err})")
            continue
        copied.append(f"{path} ({size} B)")

    with open(DELETED, "w", encoding="utf-8") as fh:
        fh.write("".join(f"{p}\n" for p in sorted(deleted)))

    with open(CHANGED, "w", encoding="utf-8") as fh:
        fh.write("".join(f"{line}\n" for line in sorted(changed_lines)))

    print(f"changed: {len(changed_lines)}, uploaded: {len(copied)}, deleted: {len(deleted)}")
    for line in copied:
        print(f"  + {line}")
    for path in sorted(deleted):
        print(f"  - {path}")
    for line in failed:
        print(f"  ! skipped {line}")

    if failed:
        print(f"::warning::{len(failed)} changed file(s) not uploaded, see the log")
    if len(copied) == 0 and len(deleted) == 0:
        print("::notice::The agent did not change any file")

    return 0


if __name__ == "__main__":
    sys.exit(main())
